regras.css:
.aj-app {min-height:100dvh; color:#172033; background:var(--page); position:relative;} 
.aj-main{width:min(100%,720px);margin:auto;padding:22px 16px 38px;display:grid;gap:12px;} 
.aj-main > *{min-width:0;}.aj-main > section{min-width:0;} 
.app-header{width:100%}.aj-headline{color:var(--primary);font-size:24px;line-height:1.2;margin:0 0 5px}
.aj-eyebrow{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--gold);font-weight:900}
.aj-subtitle{color:var(--muted);font-size:13px;line-height:1.55;margin:0}
.aj-card{padding:16px;background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 3px 11px #10233f09}
.aj-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.aj-tile{display:flex;align-items:center;gap:12px;min-height:88px;padding:13px;border:1px solid var(--line);border-radius:13px;background:#fff;color:var(--text);text-align:left;cursor:pointer;}
.aj-tile:hover{background:#f8fbff;border-color:#b1cae9}.aj-tile-icon{font-size:24px;flex:none}.aj-tile strong,.aj-tile small{display:block}.aj-tile strong{font-size:13px}.aj-tile small{font-size:11px;color:#65758b;margin-top:4px;line-height:1.45}
.aj-pill{display:inline-flex;padding:5px 10px;border-radius:999px;background:#e8f1ff;color:#244c7e;font-size:10px;font-weight:900}
.aj-primary,.aj-secondary{min-height:40px;padding:9px 13px;border-radius:10px;font-size:12px;font-weight:800;cursor:pointer;}
.aj-primary{background:var(--primary);border:1px solid var(--primary);color:#fff}.aj-secondary{background:#fff;border:1px solid #bbd0e8;color:#173c6b}
.aj-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.aj-status-warning{background:#fffaf0;border-color:#efd4a4}.aj-status-success{background:#f2fcf6;border-color:#a6ddba}
.aj-status-line{display:flex;justify-content:space-between;gap:8px;align-items:center}.aj-list{display:grid;gap:8px}.aj-small{font-size:12px;color:var(--muted);line-height:1.55}
.aj-section-title{font-size:17px;letter-spacing:-.02em;color:var(--primary);margin:0 0 9px}
.aj-inline-menu{display:flex;gap:6px;flex-wrap:wrap}.aj-inline-menu button{font-size:11px;padding:8px 9px;border-radius:8px;background:#f2f6fc;color:#294667;border:1px solid #cbdcf0}
.aj-inline-menu button[aria-current="page"]{background:#dbeafe;border-color:#95b4df;font-weight:900}
.aj-placeholder{padding:16px;border:1px dashed #afc3df;border-radius:12px;background:#f8fbff;color:#546a83;font-size:12px;line-height:1.55}
.drawer-nav .aj-group-button{font-weight:700;background:#ffffff0b}.drawer-nav .aj-group-button span{flex:1}
.drawer-nav .aj-subnav{display:grid;gap:0;background:rgba(0,0,0,.12);}.drawer-nav .aj-subnav[hidden]{display:none!important}
.drawer-nav .aj-subnav button{min-height:42px!important;padding:11px 14px 11px 53px!important;font-size:12px!important;}
.drawer-nav .aj-subnav button:disabled{opacity:.5}
@media (max-width:400px){.aj-grid{grid-template-columns:1fr}}

.app[data-area="profissional"] .aj-office-module{display:none!important}.app[data-area="escritorio"] .app-titlebar,.app[data-area="escritorio"] .hero-shell,.app[data-area="escritorio"] .online-card,.app[data-area="escritorio"] .requests-block{display:none!important}.app[data-area="escritorio"] .aj-office-module{display:block!important}.app[data-area="escritorio"] .app-main{display:block;} .app[data-area="escritorio"] .aj-office-module>*+*{margin-top:12px} .aj-office-module [data-office-state]:not([data-office-state="x"]){ } .app[data-office-state="sem_escritorio"] .only-office-active,.app[data-office-state="convite_pendente"] .only-office-active,.app[data-office-state="suspenso"] .only-office-active{display:none!important}.app[data-office-state="ativo"] .only-office-empty{display:none!important}.app:not([data-office-view="inicio"]) .office-intro{display:none!important}
